```typescript
type User = { id: number; name: string };
const users: User[] = [{ id: 1, name: "Ari" }];

function nameFor(id: number): string {
  const user = users.find((item) => item.id === id);
  if (!user) return "Unknown user";
  return user.name;
}

console.log(nameFor(2));
```
